import pyvista as pv, numpy as np
def to_pv(faces, tol=0.004):
    meshes=[]
    for f in faces:
        v,t = f.tessellate(tol)
        pts=np.array([[p.X,p.Y,p.Z] for p in v]); tri=np.array(t)
        meshes.append(pv.PolyData(pts, np.hstack([np.full((len(tri),1),3),tri]).ravel()))
    return meshes
