def foam(cls, obj, body, loc="system"):
    hdr = ("FoamFile\n{\n    version 2.0;\n    format ascii;\n    class %s;\n    object %s;\n}\n" % (cls, obj))
    open(f"{loc}/{obj}", "w").write("/*--------*- C++ -*----------*/\n"+hdr+body+"\n")

